def test_non_aggregate_invariant(safe_db):
    invariant_id = safe_db.add_import_invariant("t", "id < 10")
    assert invariant_id
    assert safe_db.list_import_invariants("t") == [
        {"id": invariant_id, "expression": "id < 10"}
    ]
    assert safe_db.safe_bulk_insert("t", [{"id": 1}, {"id": 2}]) == {
        "success": True
    }
    assert safe_db["t"].count == 2
    assert list(safe_db["t"].rows) == [{"id": 1}, {"id": 2}]
    assert safe_db.validate_import_invariants("t") == {
        "valid": True,
        "failures": [],
    }
    result = safe_db.safe_bulk_insert("t", [{"id": 3}, {"id": 100}])
    assert result["success"] is False
    assert "checkpoint_id" in result
    assert result["failures"]
    failure = result["failures"][0]
    assert failure["id"] == invariant_id
    assert failure["expression"] == "id < 10"
    assert "error" in failure
    assert result["error_report"]
    assert safe_db["t"].count == 2
    assert list(safe_db["t"].rows) == [{"id": 1}, {"id": 2}]
    assert safe_db.validate_import_invariants("t") == {
        "valid": True,
        "failures": [],
    }

it('adds and removes traits', () => {
        const world = createWorld();
        const subject = world.spawn();
        const targetA = world.spawn();
        const targetB = world.spawn();

        subject.add(Likes(targetA));
        expect(subject.has(Likes(targetA))).toBe(true);
        expect(subject.targetsFor(Likes)).toEqual([targetA]);

        world.deferred.addExclusive(subject, Likes(targetB));

        expect(subject.has(Likes(targetA))).toBe(false);
        expect(subject.has(Likes(targetB))).toBe(true);
        expect(subject.targetsFor(Likes)).toEqual([targetB]);

        world.deferred.flush();

        expect(subject.has(Likes(targetA))).toBe(false);
        expect(subject.has(Likes(targetB))).toBe(true);
        expect(subject.targetsFor(Likes)).toEqual([targetB]);
    });

it('spawns entities on flush', () => {
        const world = createWorld();
        const added: number[] = [];
        world.onAdd(A, (entity) => added.push(entity));

        const entity = world.deferred.spawn(A({ value: 1 }));

        expect(entity.has(A)).toBe(true);
        expect(entity.get(A)!.value).toBe(1);
        expect(world.has(entity)).toBe(true);
        expect(world.entities).not.toContain(entity);
        expect(added).toEqual([]);

        world.deferred.flush();

        expect(world.entities).toContain(entity);
        expect(entity.get(A)!.value).toBe(1);
        expect(added).toEqual([entity]);

        added.length = 0;
        const spawned = world.deferred.spawn(A({ value: 2 }));
        world.deferred.destroy(spawned);

        expect(spawned.isAlive()).toBe(false);
        expect(spawned.has(A)).toBe(false);

        world.deferred.flush();

        expect(world.has(spawned)).toBe(false);
        expect(added).toEqual([]);
    });
